import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import {chromium,webkit,firefox} from 'playwright';

const BASE='https://ai-shogi-yaneuraou-iphone.vercel.app/shogi-v21528/index.html';
const CLOUD='https://htvfcdktdjtyoyzrohji.supabase.co/functions/v1/shogi-save';
const RUN=Date.now();
const COPY_CODE='abcdefghijklmnopqrstuvwxyzABCDEFGH';
const UA={iphone:'Mozilla/5.0 (iPhone; CPU iPhone OS 18_6 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.6 Mobile/15E148 Safari/604.1',fire:'Mozilla/5.0 (Linux; U; en-US; KFAPWI Build/JDQ39) AppleWebKit/535.19 (KHTML, like Gecko) Silk/3.13 Safari/535.19 Silk-Accelerated=true',chrome:'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Safari/537.36',firefox:'Mozilla/5.0 (X11; Ubuntu; Linux x86_64; rv:142.0) Gecko/20100101 Firefox/142.0'};
const ENVS=[['DESKTOP_CHROMIUM',chromium,UA.chrome,{width:1440,height:900},128],['IPHONE_WEBKIT',webkit,UA.iphone,{width:390,height:844},32],['FIRE_SILK',chromium,UA.fire,{width:800,height:1280},48],['FIREFOX',firefox,UA.firefox,{width:1440,height:900},128]];
const sleep=ms=>new Promise(r=>setTimeout(r,ms));

async function seedCopy(ctx,name){await ctx.addInitScript(({COPY_CODE,name,CLOUD})=>{localStorage.setItem('aiShogiCloudConfigV1',JSON.stringify({syncKey:COPY_CODE,deviceId:'pr89copy_'+name,api:CLOUD,enabled:true}));localStorage.setItem('aiShogiCloudMetaV1',JSON.stringify({revision:0,lastSyncedSavedAt:0,pending:false,lastError:'',updatedAt:Date.now()}));Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async text=>{window.__copiedSyncCode=text;}}});},{COPY_CODE,name,CLOUD})}
async function waitApp(p){await p.waitForFunction(()=>window.crossOriginIsolated&&document.querySelectorAll('#chars .ch').length===26&&window.AI_SHOGI_YANEURAOU_FUTURE?.strengthTune==='fullsearch-20260825'&&window.AI_SHOGI_YANEURAOU_TOP5?.version==='2.15.32-tune5'&&window.AI_SHOGI_SAVE&&window.AI_SHOGI_CLOUD_SAVE?.version==='21531d'&&document.getElementById('cloudCodeBtn')&&document.getElementById('cloudPullBtn'),null,{timeout:150000});await sleep(300)}
function initialBoard(){const b=Array(81).fill(null),back=['L','N','S','G','K','G','S','N','L'];for(let i=0;i<9;i++){b[i]={k:back[i],o:-1};b[72+i]={k:back[8-i],o:1};b[18+i]={k:'P',o:-1};b[54+i]={k:'P',o:1}}b[10]={k:'R',o:-1};b[16]={k:'B',o:-1};b[64]={k:'B',o:1};b[70]={k:'R',o:1};return b}
async function runEnv(name,type,userAgent,viewport,hashMB){const b=await type.launch({headless:true}),ctx=await b.newContext({userAgent,viewport});await seedCopy(ctx,name);await ctx.route(CLOUD,r=>r.fulfill({status:200,contentType:'application/json',body:JSON.stringify({ok:true,record:null})}));const p=await ctx.newPage();const errors=[];p.on('pageerror',e=>errors.push(String(e.message||e)));try{await p.goto(BASE+'?pr89public='+name+'-'+RUN,{waitUntil:'domcontentloaded',timeout:120000});await waitApp(p);const before=await p.evaluate(()=>({coi:crossOriginIsolated,cards:document.querySelectorAll('#chars .ch').length,unique:new Set([...document.querySelectorAll('#chars .ch')].map(x=>(x.querySelector('.chName')?.textContent||x.querySelector('img')?.alt||'').trim())).size,version:AI_SHOGI_CLOUD_SAVE.version,top5:AI_SHOGI_YANEURAOU_TOP5.version,buttons:AI_SHOGI_CLOUD_SAVE.audit().buttons,disabled:document.getElementById('cloudCodeBtn').disabled,overflow:document.documentElement.scrollWidth>innerWidth+1}));assert.equal(before.coi,true);assert.equal(before.cards,26);assert.equal(before.unique,26);assert.equal(before.version,'21531d');assert.equal(before.top5,'2.15.32-tune5');assert.deepEqual(before.buttons,{cloud:true,codeCopy:true,pull:true});assert.equal(before.disabled,false);assert.equal(before.overflow,false);const copied=await p.evaluate(async()=>{const ok=await AI_SHOGI_CLOUD_SAVE.copySyncCode();return {ok,text:window.__copiedSyncCode,status:document.getElementById('status')?.textContent||''}});assert.equal(copied.ok,true);assert.equal(copied.text,COPY_CODE);assert.ok(copied.status.includes('コピー'));const state={b:initialBoard(),h:{1:{},'-1':{}},t:1,log:[],last:null};const eng=await p.evaluate(async state=>{const x=AI_SHOGI_YANEURAOU_FUTURE;await x.init();const r=await x.bestMove(state,{ms:300,multiPV:1,adaptive:false});return {status:x.status(),info:r?.info||{},ok:!!(r?.move||r?.resign||r?.declareWin)}},state);assert.equal(eng.status.ready,true);assert.equal(eng.status.worker,true);assert.equal(eng.info.hashMB,hashMB);assert.equal(eng.info.threads,1);assert.equal(eng.ok,true);assert.deepEqual(errors,[]);console.log('PR89_PUBLIC_ENV '+JSON.stringify({name,coi:true,cards:26,unique:26,cloudVersion:before.version,top5:before.top5,buttons:before.buttons,clipboardExact:true,hashMB,threads:1,realBestMove:true,overflow:false,pageErrors:errors}))}finally{await ctx.close();await b.close()}}
for(const e of ENVS)await runEnv(...e);

function save(marker,savedAt=Date.now()){return {version:1,savedAt,ci:25,st:{b:Array(81).fill(null),h:{1:{},'-1':{}},t:1,log:[{cloudTest:marker}],last:null}}}
async function seed(ctx,deviceId,localSave=null){await ctx.addInitScript(({deviceId,CLOUD,localSave})=>{localStorage.setItem('aiShogiCloudConfigV1',JSON.stringify({syncKey:'',deviceId,api:CLOUD,enabled:false}));localStorage.setItem('aiShogiCloudMetaV1',JSON.stringify({revision:0,lastSyncedSavedAt:0,pending:false,lastError:'',updatedAt:Date.now()}));if(localSave)localStorage.setItem('aiShogiGameSaveV1',JSON.stringify(localSave));else localStorage.removeItem('aiShogiGameSaveV1')},{deviceId,CLOUD,localSave})}
async function proxyReal(route){const req=route.request(),h=req.headers(),headers={};if(h.authorization)headers.Authorization=h.authorization;if(h['content-type'])headers['Content-Type']=h['content-type'];try{const r=await fetch(CLOUD,{method:req.method(),headers,body:['GET','HEAD'].includes(req.method())?undefined:req.postData(),signal:AbortSignal.timeout(20000)});await route.fulfill({status:r.status,contentType:r.headers.get('content-type')||'application/json',body:await r.text()})}catch(e){await route.fulfill({status:599,contentType:'application/json',body:JSON.stringify({ok:false,error:'proxy_'+String(e.message||e)})})}}
const code=crypto.randomBytes(24).toString('base64url'),wb=await webkit.launch({headless:true}),cb=await chromium.launch({headless:true});const ic=await wb.newContext({userAgent:UA.iphone,viewport:{width:390,height:844}}),pc=await cb.newContext({userAgent:UA.chrome,viewport:{width:1440,height:900}});await ic.route(CLOUD,proxyReal);await pc.route(CLOUD,proxyReal);await seed(ic,'pr89final_iphone_'+RUN,save('IPHONE-A',RUN));await seed(pc,'pr89final_pc_'+RUN,null);const ip=await ic.newPage(),cp=await pc.newPage();try{await ip.goto(BASE+'?pr89mixed=i-'+RUN,{waitUntil:'domcontentloaded',timeout:120000});await waitApp(ip);assert.equal(await ip.evaluate(()=>AI_SHOGI_CLOUD_SAVE.version),'21531d');assert.equal(await ip.evaluate(c=>AI_SHOGI_CLOUD_SAVE.enableWithCode(c),code),true);await ip.waitForFunction(()=>{const m=AI_SHOGI_CLOUD_SAVE.meta();return m.revision>=1&&!m.pending&&m.lastError==='' },null,{timeout:30000});const iRev=await ip.evaluate(()=>AI_SHOGI_CLOUD_SAVE.meta().revision);await cp.goto(BASE+'?pr89mixed=p-'+RUN,{waitUntil:'domcontentloaded',timeout:120000});await waitApp(cp);assert.equal(await cp.evaluate(()=>AI_SHOGI_CLOUD_SAVE.version),'21531d');assert.equal(await cp.evaluate(c=>AI_SHOGI_CLOUD_SAVE.enableWithCode(c),code),true);await cp.waitForFunction(()=>JSON.parse(localStorage.getItem('aiShogiGameSaveV1')||'null')?.st?.log?.at(-1)?.cloudTest==='IPHONE-A',null,{timeout:30000});const p0=await cp.evaluate(()=>AI_SHOGI_CLOUD_SAVE.meta());assert.equal(p0.revision,iRev);await cp.evaluate(v=>{localStorage.setItem('aiShogiGameSaveV1',JSON.stringify(v));window.dispatchEvent(new Event('ai-shogi-local-save'))},save('PC-B',RUN+1000));await cp.waitForFunction(r=>{const m=AI_SHOGI_CLOUD_SAVE.meta();return m.revision>r&&!m.pending&&m.lastError==='' },p0.revision,{timeout:30000});const pRev=await cp.evaluate(()=>AI_SHOGI_CLOUD_SAVE.meta().revision);await ip.evaluate(v=>{localStorage.setItem('aiShogiGameSaveV1',JSON.stringify(v));window.dispatchEvent(new Event('ai-shogi-local-save'))},save('IPHONE-A-PENDING',RUN+2000));await ip.waitForFunction(()=>{const m=AI_SHOGI_CLOUD_SAVE.meta();return m.pending&&m.lastError==='conflict'},null,{timeout:30000});const protectedPull=await ip.evaluate(()=>AI_SHOGI_CLOUD_SAVE.pull());assert.equal(protectedPull.localPending,true);ip.once('dialog',d=>d.accept());await ip.click('#cloudPullBtn');await ip.waitForFunction(()=>{const m=AI_SHOGI_CLOUD_SAVE.meta(),x=JSON.parse(localStorage.getItem('aiShogiGameSaveV1')||'null');return !m.pending&&m.lastError===''&&x?.st?.log?.at(-1)?.cloudTest==='PC-B'},null,{timeout:30000});const fin=await ip.evaluate(()=>({m:AI_SHOGI_CLOUD_SAVE.meta(),marker:JSON.parse(localStorage.getItem('aiShogiGameSaveV1')).st.log.at(-1).cloudTest,version:AI_SHOGI_CLOUD_SAVE.version}));assert.ok(fin.m.revision>=pRev);assert.equal(fin.m.pending,false);assert.equal(fin.m.lastError,'');assert.equal(fin.marker,'PC-B');assert.equal(fin.version,'21531d');console.log('PR89_PUBLIC_MIXED '+JSON.stringify({iphoneInitialRevision:iRev,pcRevision:pRev,iphoneFinalRevision:fin.m.revision,cloudVersion:fin.version,realBackend:true,conflictProtected:true,explicitDiscardRestored:true,finalMarker:fin.marker,devicePrefix:'pr89final_'}))}finally{await ic.close();await pc.close();await wb.close();await cb.close()}
console.log('PASS_POSTMERGE_PR89_CLOUD_VERSION_21531D');
